  "items": [
    {
      "original_text": "grep -r \"plugins/dso\" plugins/dso/ returns zero matches across the distributed plugin tree (verifiable in CI on every commit)",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable, verifiable system property that persists after work is complete and can be continuously validated"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "A project-local pre-commit hook (.claude/hooks/pre-commit/check-plugin-self-ref.sh) blocks commits that introduce the string plugins/dso into any file under plugins/dso/ \u2014 no suppression mechanism, no annotation bypass",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system safeguard that will remain in place and enforce constraints on future commits"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "All scripts in plugins/dso/scripts/ and plugins/dso/hooks/ that reference other plugin files use _PLUGIN_ROOT and pass a test confirming resolution from both shim context and direct invocation",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable property of the system where scripts consistently use proper plugin root resolution and pass validation tests"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "All agent and skill markdown files that reference plugin-internal paths use the ${CLAUDE_PLUGIN_ROOT}/ prefix, verifiable by grep on the distributed tree",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable property of the system (markdown files conform to a path-prefix standard) that is verifiable and ongoing, despite the verification method mentioned"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "plugin-boundary-allowlist.conf is relocated from plugins/dso/ to .claude/hooks/pre-commit/ with all references updated",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 5,
        "rationale": "describes a one-time file relocation and reference update task, not an ongoing system property"
      },
      "user_decision": "auto",
      "post_migration_section": "CC"
    },
    {
      "original_text": "Migration tooling (migrate_comment_refs.py and any S2/S3 equivalents) does not exist under plugins/dso/ \u2014 created at repo root, deleted after use and before enforcement hook activates",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 5,
        "rationale": "describes a one-time migration task with explicit lifecycle (creation, use, deletion) rather than a durable system property"
      },
      "user_decision": "auto",
      "post_migration_section": "CC"
    }
  ]
}
